//! Independent byte ABI audit; expectations are published vectors and py_ecc,
//! never generated by the implementation under test. Built-in implementation
//! tests also compile here but are excluded by the `audit_` test filter.
#![allow(dead_code)]
#[path = "../../../plugins/bls12-381/runtime/src/lib.rs"]
mod runtime;
fn hex(s: &str) -> Vec<u8> {
    assert_eq!(s.len() % 2, 0);
    s.as_bytes().chunks_exact(2).map(|p| u8::from_str_radix(core::str::from_utf8(p).unwrap(), 16).unwrap()).collect()
}
#[test]
fn audit_independent_vectors_guarded_abi() {
    let mut count=0;
    for line in include_str!("vectors.tsv").lines().chain(include_str!("msm-vectors.tsv").lines()) {
        let v: Vec<_> = line.split('\t').collect();
        let op: u32 = v[1].parse().unwrap();
        let inputs=[hex(v[2]),hex(v[3]),hex(v[4])];
        let saved=inputs.clone();
        let size=match op {1|3|5|7|9|11|17=>48,2|4|6|8|10|12|18=>96,_=>1};
        let mut output=vec![0xa5;size+34];
        let ptr=|i: usize| if inputs[i].is_empty() { core::ptr::null() } else {inputs[i].as_ptr()};
        let status=unsafe{runtime::bls_call(op,ptr(0),inputs[0].len(),ptr(1),inputs[1].len(),ptr(2),inputs[2].len(),output.as_mut_ptr().add(17))};
        assert_eq!(status,v[5].parse::<u32>().unwrap(),"{}",v[0]);
        assert_eq!(inputs,saved,"input immutability {}",v[0]);
        assert!(output[..17].iter().chain(output[size+17..].iter()).all(|&x|x==0xa5),"output bounds {}",v[0]);
        if status==0 {assert_eq!(&output[17..17+size],&hex(v[6]),"{}",v[0])}
        else {assert!(output.iter().all(|&x|x==0xa5),"error modified output {}",v[0])}
        count+=1;
    }
    eprintln!("independent native ABI vectors passed: {count}");
}
